import { readFileSync, writeFileSync } from "fs";
import { checkpoint } from "@tigrisdata/agent-kit";
import path from "path";

async function main() {
  const baseDir = "/home/user/ckpt-tag";

  // 1. Read the build id
  const buildId = readFileSync(path.join(baseDir, "build_id.txt"), "utf-8").trim();

  // 2. Compute a unix timestamp
  const unixTimestamp = Math.floor(Date.now() / 1000);

  // Get trial_id to construct bucket name
  const trialId = readFileSync("/logs/artifacts/trial_id", "utf-8").trim();

  // Construct bucket name: harbor-pipeline-${trial_id}
  // normalized to lowercase, invalid characters replaced with hyphens
  const rawBucketName = `harbor-pipeline-${trialId}`;
  const bucketName = rawBucketName.toLowerCase().replace(/[^a-z0-9]/g, "-");

  // 3. Take a named checkpoint
  const name = `release-${buildId}-${unixTimestamp}`;

  const { data: ckpt, error } = await checkpoint(bucketName, { name });
  if (error) {
    throw error;
  }

  if (!ckpt || !ckpt.snapshotId) {
    throw new Error("Failed to get snapshotId from checkpoint response");
  }

  // 4. Persist the result
  const result = {
    snapshotId: ckpt.snapshotId,
    name: name
  };

  writeFileSync(path.join(baseDir, "snapshot.json"), JSON.stringify(result));
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

